// 4-bit Fibonacci LFSR, p(x) = x^4 + x^3 + 1
module lfsr4 (
  input  logic       clk, rst_n,
  output logic [4:1] q          // q[1] = Q1 ... q[4] = Q4
);
  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) q <= 4'b0001;            // seed: Q1 = 1, never all zeros
    else        q <= {q[3:1], q[3] ^ q[4]}; // shift right, feedback into Q1
endmodule
